// 本片数字由 scratchpad/v15.py 独立核算：
//   方差阶梯（H=8，每批 200 条轨迹 × 400 批，真值 0.9000）：
//     IS   均值 0.8848  标准差 0.5102  MSE 0.260540
//     PDIS 均值 0.8870  标准差 0.1879  MSE 0.035488   （MSE 降 7.3 倍）
//     WIS  均值 0.8759  标准差 0.0540  MSE 0.003492   （再降 10.2 倍，且可见偏差）
//   控制变量反例：Var(X)=1.9945 Var(Y)=1.3019 Cov=0.6985
//     讲座判据 Cov>Var(Y) 判「别用」；正确判据 2Cov>Var(Y) 判「该用」；实测 Var 降到 1.8995
//   从「−5 百万」反推 Hoeffding 的 range b：δ=0.05 时约 1.29e9（理论上界 1e200 更大）
//   MSE = 偏差² + 方差：偏差 0.5 方差 0.1 -> 0.35，说成「偏差+方差」是 0.60
function isWeight(pe,pb,L){return Math.pow(pe/pb,L);}
function hoeffCoef(n,d){return Math.sqrt(Math.log(1/d)/(2*n));}
function mseOf(bias,varr){return bias*bias+varr;}

/* ══ L15 片内图 ════════════════════════════════════════════════════
   这一讲反复要画两样东西：某个状态上一个策略给各动作的概率，
   以及「估计值打在靶上」的偏差/方差对比。 */

/* 一个策略在某状态上的动作概率条。p 是概率数组，0 的那根画成空心 */
function pBars(o){
  var x0=o.x,y0=o.y,w=o.w||34,gap=o.gap||46,h=o.h||96;
  for(var i=0;i<o.p.length;i++){
    var x=x0+i*gap, ph=h*o.p[i];
    E.gS.append("rect").attr("class","cellbg").attr("x",x).attr("y",y0-h)
      .attr("width",w).attr("height",h).attr("rx",3).attr("opacity",0.32);
    if(o.p[i]>0)
      E.gS.append("rect").attr("class","vbar "+((o.cls&&o.cls(i))||"g"))
        .attr("x",x).attr("y",y0-ph).attr("width",w).attr("height",ph).attr("rx",3);
    if(o.lab)note(o.lab(i),x+w/2,y0+20,"sm");
  }
  if(o.name)note(o.name,x0-30,y0-h/2,o.ncls||"sm");
}

/* 打靶图：靶心是真值，点是若干次估计。看偏差（整体偏不偏）和方差（散不散） */
function bullseye(o){
  for(var r=3;r>=1;r--)
    E.gS.append("circle").attr("class","cellbg").attr("cx",o.x).attr("cy",o.y)
      .attr("r",r*22).attr("opacity",0.16+0.06*(3-r));
  E.gS.append("circle").attr("class","tnode y").attr("cx",o.x).attr("cy",o.y).attr("r",3.5);
  var pts=[];
  for(var k=0;k<o.n;k++){
    var a=k*2.399, rr=o.sd*Math.sqrt((k+0.5)/o.n);
    pts.push([o.x+o.bx+Math.cos(a)*rr, o.y+o.by+Math.sin(a)*rr]);}
  dots(pts,o.cls||"g",4);
}

